355	+function drFillLine(L: DrLine, jcts: DrRect[], out: DrPad[]): void {
356	+  const X = L.along === 'x';
357	+  const sides: [string, number][] = X ? [['N', -1], ['S', 1]] : [['W', -1], ['E', 1]];
358	+  const emit = (id: string, kind: DrPad['kind'], a: number, b: number, y: DrY, lout: number, gate?: string) => {
359	+    for (const [sfx, s] of sides) {
360	+      const c0 = L.c + s * L.lin, c1 = L.c + s * lout, lo = Math.min(c0, c1), hi = Math.max(c0, c1);
361	+      const p: DrPad = X ? { id: `${id}.${sfx}`, kind, x0: a, x1: b, z0: lo, z1: hi, y } : { id: `${id}.${sfx}`, kind, x0: lo, x1: hi, z0: a, z1: b, y };
362	+      if (gate) p.gate = gate;
363	+      out.push(p);
364	+    }
