374	+  for (const s of L.spans || []) cuts.push({ a: s.a, b: s.b, span: s });
375	+  cuts.sort((p, q) => p.a - q.a);
376	+  let cur = L.a, k = 0;
377	+  for (const c of cuts) {
378	+    if (c.a > cur + 1e-6) emit(`${L.id}.${k++}`, 'road', cur, Math.min(c.a, L.b), L.y, L.lout);
