+  id: string; along: 'x' | 'z'; c: number; lin: number; lout: number;   // tim tuyến (z nếu dọc X, x nếu dọc Z), mép trong / ngoài mỗi chiều tính từ tim
+  a: number; b: number; y: DrY;                                     // đoạn dọc tuyến, cao độ phần đường thường
