+    add(`jct.${V.id}.dragon.S`, x0, x1, SD.zIn, SD.zOut);
+    add(`jct.${V.id}.ttl.N`, x0, x1, TTL.z - ST.zOut, TTL.z - ST.zIn);
+    add(`jct.${V.id}.ttl.S`, x0, x1, TTL.z + ST.zIn, TTL.z + ST.zOut);
+  }
