+  add('jct.dragon.E', DR_X, DR_X + SD.jLen, -SD.zOut, SD.zOut);
+  add('jct.ttl.W', TTL_W - ST.jLen, TTL_W, TTL.z - ST.zOut, TTL.z + ST.zOut);
+  add('jct.ttl.E', TTL_E, TTL_E + ST.jLen, TTL.z - ST.zOut, TTL.z + ST.zOut);
